function parseAuditFrames(log) {
 const frames=[], labels=new Set(); let active=null;
 for (const line of log.split("\n")) {
  const match=line.match(/^\ufeff?\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d+Z LSC_AUDIT_FRAME_(BEGIN|CHUNK|END) (.*)$/);
  if(!match) continue;
  const [,kind,raw]=match;
  if(kind==="BEGIN") {
   if(active) throw Error("nested frame");
   const meta=JSON.parse(raw);
   if(labels.has(meta.label)||meta.encoding!=="gzip+base64"||meta.chunk_characters!==8192||!Number.isSafeInteger(meta.chunks)||meta.chunks<=0)throw Error("frame admission");
   for(const key of ["bytes","compressed_bytes","raw_limit"])if(!Number.isSafeInteger(meta[key])||meta[key]<0)throw Error("frame sizes");
   if(meta.bytes>meta.raw_limit||meta.compressed_bytes>4*1024*1024||!["sha256","compressed_sha256"].every(key=>/^[0-9a-f]{64}$/.test(meta[key])))throw Error("frame bounds");
   active={meta,header:raw,chunks:[]};
  } else if(kind==="CHUNK") {
   const m=raw.match(/^(\S+) (\d+)\/(\d+) ([A-Za-z0-9+/=]+)$/);
   if(!active||!m||m[1]!==active.meta.label||Number(m[2])!==active.chunks.length+1||Number(m[3])!==active.meta.chunks)throw Error("chunk order");
   if(Number(m[2])<Number(m[3])&&m[4].length!==8192)throw Error("chunk width");
   if(m[4].length>8192)throw Error("final chunk width");
   active.chunks.push(m[4]);
  } else {
   if(!active||raw!==active.header||active.chunks.length!==active.meta.chunks)throw Error("frame end");
   const encoded=active.chunks.join("");
   if(encoded.length!==4*Math.ceil(active.meta.compressed_bytes/3))throw Error("encoded size");
   labels.add(active.meta.label);frames.push({label:active.meta.label,meta:active.meta,encoded});active=null;
  }
 }
 if(active||!frames.length)throw Error("missing terminal frame");
 if(frames.reduce((s,f)=>s+f.meta.bytes,0)>48*1024*1024||frames.reduce((s,f)=>s+f.meta.compressed_bytes,0)>8*1024*1024)throw Error("aggregate bounds");
 return frames;
}

